// ============================================================
// Alpha — Extract Clean Financial Analysis Payload
// Supports:
// 1. Real Backend webhook:      $json.body = analysis payload
// 2. Postman replay wrapper:    $json.body[0].body = analysis payload
// 3. Direct payload input:      $json = analysis payload
// ============================================================

const input = $input.first().json;

// ------------------------------------------------------------
// 1. Unwrap Postman/test wrapper when body is an array
// ------------------------------------------------------------

let source = input;

if (Array.isArray(source?.body)) {
  if (source.body.length !== 1) {
    throw new Error(
      `INVALID_ANALYSIS_WRAPPER: Expected exactly one body item, received ${source.body.length}`
    );
  }

  source = source.body[0];
}

// ------------------------------------------------------------
// 2. Extract the actual Backend analysis payload
// ------------------------------------------------------------

const payload =
  source?.body &&
  typeof source.body === 'object' &&
  !Array.isArray(source.body)
    ? source.body
    : source;

if (
  !payload ||
  typeof payload !== 'object' ||
  Array.isArray(payload)
) {
  throw new Error(
    'INVALID_ANALYSIS_PAYLOAD: Expected an analysis object'
  );
}

// ------------------------------------------------------------
// 3. Validate basic contract
// ------------------------------------------------------------

if (payload.schemaVersion !== '1.1') {
  throw new Error(
    `UNSUPPORTED_SCHEMA_VERSION: ${payload.schemaVersion ?? 'missing'}`
  );
}

if (payload.type !== 'analyze') {
  throw new Error(
    `INVALID_ANALYSIS_TYPE: ${payload.type ?? 'missing'}`
  );
}

const requestId = payload?.request?.id;

if (
  typeof requestId !== 'string' ||
  requestId.trim().length === 0 ||
  requestId === 'unknown'
) {
  throw new Error(
    'INVALID_REQUEST_ID: A valid Backend request ID is required'
  );
}

// ------------------------------------------------------------
// 4. Safe normalization helpers
// ------------------------------------------------------------

function objectOrNull(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  )
    ? value
    : null;
}

function arrayOrEmpty(value, max) {
  return Array.isArray(value)
    ? value.slice(0, max)
    : [];
}

function numberOrNull(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const parsed = Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

// ------------------------------------------------------------
// 5. Normalize expense categories
// Supports current legacy shape: { category, total: "25" }
// Produces clean shape: { category, amount: 25, transactionCount }
// ------------------------------------------------------------

const expenseCategories = arrayOrEmpty(
  payload.expenseCategories,
  5
).map((item) => ({
  category:
    typeof item?.category === 'string'
      ? item.category
      : 'uncategorized',

  amount: numberOrNull(
    item?.amount ?? item?.total
  ),

  transactionCount:
    numberOrNull(item?.transactionCount),
}));

// ------------------------------------------------------------
// 6. Normalize bounded recent transactions
// ------------------------------------------------------------

const recentTransactions = arrayOrEmpty(
  payload.recentTransactions,
  10
).map((item) => ({
  date: item?.date ?? null,
  type: item?.type ?? null,
  direction: item?.direction ?? null,
  status: item?.status ?? null,
  budgetBucket: item?.budgetBucket ?? null,
  amount: numberOrNull(item?.amount),
  currency:
    item?.currency ??
    payload?.userContext?.currency ??
    'JOD',
  category: item?.category ?? null,
  subcategory: item?.subcategory ?? null,
}));

// ------------------------------------------------------------
// 7. Normalize Emergency Fund semantics
// Do not turn unavailable lifetime values into verified zero.
// ------------------------------------------------------------

const rawEmergencyFund =
  objectOrNull(payload.emergencyFund) ?? {};

const emergencyExists =
  rawEmergencyFund.exists === true;

const emergencyFund = {
  exists: emergencyExists,

  plannedRate:
    numberOrNull(rawEmergencyFund.plannedRate),

  plannedCycleAmount:
    numberOrNull(rawEmergencyFund.plannedCycleAmount),

  lifetimeBalance: emergencyExists
    ? numberOrNull(
        rawEmergencyFund.lifetimeBalance ??
        rawEmergencyFund.currentBalance
      )
    : null,

  targetAmount: emergencyExists
    ? numberOrNull(rawEmergencyFund.targetAmount)
    : null,

  status: emergencyExists
    ? rawEmergencyFund.status ?? null
    : null,
};

// ------------------------------------------------------------
// 8. Build one clean object for the AI node
// ------------------------------------------------------------

const financialData = {
  schemaVersion: payload.schemaVersion,
  type: payload.type,

  request: {
    id: requestId,
    mode: payload?.request?.mode ?? 'financial_snapshot',
    requestedAt: payload?.request?.requestedAt ?? null,
    analysisAsOfDate:
      payload?.request?.analysisAsOfDate ?? null,
    language: payload?.request?.language ?? 'ar',
    timezone:
      payload?.request?.timezone ?? 'Asia/Amman',
    includeSpeechText:
      payload?.request?.includeSpeechText === true,
    maxInsights:
      numberOrNull(payload?.request?.maxInsights) ?? 3,
    maxRecommendations:
      numberOrNull(payload?.request?.maxRecommendations) ?? 3,
  },

  userContext: {
    locale:
      payload?.userContext?.locale ?? 'ar-JO',
    currency:
      payload?.userContext?.currency ?? 'JOD',
  },

  financialProfile:
    objectOrNull(payload.financialProfile),

  cycle:
    objectOrNull(payload.cycle),

  plan:
    objectOrNull(payload.plan),

  actuals:
    objectOrNull(payload.actuals),

  expenseCategories,

  recentTransactions,

  commitments: {
    paidCount:
      numberOrNull(payload?.commitments?.paidCount) ?? 0,
    upcomingCount:
      numberOrNull(payload?.commitments?.upcomingCount) ?? 0,
    overdueCount:
      numberOrNull(payload?.commitments?.overdueCount) ?? 0,
    unpaidAmount:
      numberOrNull(payload?.commitments?.unpaidAmount) ?? 0,
    items: arrayOrEmpty(
      payload?.commitments?.items,
      5
    ),
  },

  goals: {
    activeCount:
      numberOrNull(payload?.goals?.activeCount) ?? 0,
    readyCount:
      numberOrNull(payload?.goals?.readyCount) ?? 0,
    totalTargetAmount:
      numberOrNull(payload?.goals?.totalTargetAmount) ?? 0,
    totalCurrentBalance:
      numberOrNull(payload?.goals?.totalCurrentBalance) ?? 0,
    totalRemainingAmount:
      numberOrNull(payload?.goals?.totalRemainingAmount) ?? 0,
    items: arrayOrEmpty(payload?.goals?.items, 5),
  },

  emergencyFund,

  historicalCycles:
    arrayOrEmpty(payload.historicalCycles, 3),

  dataQuality:
    objectOrNull(payload.dataQuality) ?? {
      hasFinancialProfile: false,
      hasCurrentCycle: false,
      hasApprovedSnapshot: false,
      isPartialCycle: false,
      missingFields: [],
      transactionsAreConfirmedOnly: true,
      transactionDetailsAreBounded: true,
      historicalCyclesAreBounded: true,
    },

  privacy:
    objectOrNull(payload.privacy) ?? {
      containsFinancialData: true,
      dataScope: 'extended_financial_analysis',
      generatedAt: new Date().toISOString(),
    },
};

// ------------------------------------------------------------
// 9. Return clean n8n object
// ------------------------------------------------------------

return [
  {
    json: {
      requestId,
      financialData,
    },
  },
];

'use strict';

// =========================
// Helpers
// =========================

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function boundedString(value, maxLength) {
  if (typeof value !== 'string') {
    return null;
  }

  const cleaned = value.trim();

  if (!cleaned) {
    return null;
  }

  return cleaned.slice(0, maxLength);
}

function boundedStringArray(value, maxItems, maxLength) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item) => typeof item === 'string')
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, maxItems)
    .map((item) => item.slice(0, maxLength));
}

function numberOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const parsed = Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

function normalizeAnalystResult(raw) {
  let value = raw;

  if (Array.isArray(value)) {
    if (value.length === 0) {
      throw new Error('EMPTY_AI_RESULT');
    }

    value = value[0];
  }

  if (isPlainObject(value?.json)) {
    value = value.json;
  }

  if (isPlainObject(value?.output)) {
    value = value.output;
  }

  if (!isPlainObject(value)) {
    throw new Error('INVALID_AI_RESULT');
  }

  return value;
}

function calculatePercent(current, target) {
  const currentNumber = numberOrNull(current);
  const targetNumber = numberOrNull(target);

  if (
    currentNumber === null ||
    targetNumber === null ||
    targetNumber <= 0
  ) {
    return 0;
  }

  return Number(
    ((currentNumber / targetNumber) * 100).toFixed(2)
  );
}

// Higher savings percentage is better.
function calculateSavingsStatus(percent) {
  if (percent >= 100) {
    return 'completed';
  }

  if (percent >= 80) {
    return 'on_track';
  }

  if (percent >= 50) {
    return 'moderate';
  }

  return 'warning';
}

// Lower spending percentage is better.
function calculateSpendingStatus(percent) {
  if (percent <= 50) {
    return 'on_track';
  }

  if (percent <= 80) {
    return 'warning';
  }

  if (percent <= 100) {
    return 'critical';
  }

  return 'exceeded';
}

// =========================
// Financial Data
// =========================

const financialSource =
  $('normalization input')
    .first()
    .json ?? {};

const financialData =
  financialSource.financialData;

if (!isPlainObject(financialData)) {
  throw new Error(
    'MISSING_FINANCIAL_DATA: financialData is required'
  );
}

const actuals =
  isPlainObject(financialData.actuals)
    ? financialData.actuals
    : {};

const plan =
  isPlainObject(financialData.plan)
    ? financialData.plan
    : {};

// =========================
// UI Metrics
// =========================

const savingsCurrent =
  numberOrNull(actuals.confirmedSavings) ?? 0;

const needsCurrent =
  numberOrNull(actuals.needsSpent) ?? 0;

const wantsCurrent =
  numberOrNull(actuals.wantsSpent) ?? 0;

const savingsTarget =
  numberOrNull(plan?.savings?.targetAmount) ?? 0;

const needsTarget =
  numberOrNull(plan?.needs?.targetAmount) ?? 0;

const wantsTarget =
  numberOrNull(plan?.wants?.targetAmount) ?? 0;

const savingsPercent = calculatePercent(
  savingsCurrent,
  savingsTarget
);

const needsPercent = calculatePercent(
  needsCurrent,
  needsTarget
);

const wantsPercent = calculatePercent(
  wantsCurrent,
  wantsTarget
);

const uiMetrics = {
  savings: {
    current: savingsCurrent,
    target: savingsTarget,
    percent: savingsPercent,
    status: calculateSavingsStatus(savingsPercent),
  },

  needs: {
    current: needsCurrent,
    target: needsTarget,
    percent: needsPercent,
    status: calculateSpendingStatus(needsPercent),
  },

  wants: {
    current: wantsCurrent,
    target: wantsTarget,
    percent: wantsPercent,
    status: calculateSpendingStatus(wantsPercent),
  },
};

// =========================
// Cloudinary Audio
// =========================

const cloudinaryOutput = $input.first().json ?? {};

const rawAudioUrl =
  cloudinaryOutput.secure_url ??
  cloudinaryOutput.url ??
  cloudinaryOutput.data?.secure_url ??
  cloudinaryOutput.data?.url ??
  cloudinaryOutput.body?.secure_url ??
  cloudinaryOutput.body?.url ??
  cloudinaryOutput.response?.secure_url ??
  cloudinaryOutput.response?.url ??
  null;

const rawAudioDuration =
  cloudinaryOutput.duration ??
  cloudinaryOutput.data?.duration ??
  cloudinaryOutput.body?.duration ??
  cloudinaryOutput.response?.duration ??
  null;

let audioUrl = null;
let audioDuration = null;

if (
  typeof rawAudioUrl === 'string' &&
  rawAudioUrl.trim() !== ''
) {
  audioUrl = rawAudioUrl.trim();
}

const parsedAudioDuration =
  numberOrNull(rawAudioDuration);

if (
  parsedAudioDuration !== null &&
  parsedAudioDuration >= 0
) {
  audioDuration = parsedAudioDuration;
}

const audio = {
  url: audioUrl,
  duration: audioDuration,
};
// =========================
// AI Analyst Output
// =========================

const analystOutput =
  $('04 — Alpha Financial Analyst')
    .first()
    .json;

const analystData =
  normalizeAnalystResult(analystOutput);

const summary = boundedString(
  analystData.summary,
  4000
);

if (!summary) {
  throw new Error(
    'INVALID_AI_SUMMARY: A non-empty summary is required'
  );
}

const insights = boundedStringArray(
  analystData.insights,
  3,
  1500
);

const recommendations = boundedStringArray(
  analystData.recommendations,
  3,
  1500
);

const speechText = boundedString(
  analystData.speechText,
  8000
);

// =========================
// Response
// =========================

return [
  {
    json: {
      status: 'success',

      content: {
        summary,
        insights,
        recommendations,
        speechText,
      },

      uiMetrics,

      audio,
    },
  },
];
